window.ANTZ_I18N = {"meta":{"lang":"ru","source":false,"reviewed":false,"translator":"machine (Claude)"},"ui":{"brand.title":"Руководство по началу работы с Antz","brand.label":"Руководство по началу работы","brand.home":"Antz Systems, главная","meta.description":"Краткое наглядное руководство по платформе Antz для команд по уходу за животными.","nav.primary":"Основная навигация","nav.menu":"Меню","nav.modules":"Модули","nav.why":"Почему Antz","nav.start":"Начало работы","nav.faq":"Вопросы и ответы","nav.search":"Поиск по руководству","nav.searchTip":"Поиск (Ctrl/Cmd + K)","footer.tagline":"Хорошие данные = полезные выводы = здоровые животные","footer.explore":"Разделы","footer.talk":"Связаться с нами","footer.rights":"© 2026 Antz Systems. Все права защищены.","lang.label":"Язык","lang.note":"Эта страница переведена машинным способом и ожидает проверки носителем языка.","lang.english":"Открыть на английском","lang.dismiss":"Закрыть","lang.inApp":"В приложении: {x}","hero.title":"Одна платформа для всех животных, о которых вы заботитесь","hero.sub":"Учёт, повседневная работа и командное взаимодействие на всех ваших площадках. Найдите любую задачу в Antz — с настоящими экранами.","hero.areas":"Направлений работы: {n}","hero.devices":"Мобильное и веб-приложение","search.label":"Поиск по модулям и функциям","search.cue":"Поиск: {x}","search.clear":"Очистить поиск","search.short":"Введите не менее двух букв, чтобы искать по всем модулям и функциям.","search.top":"Лучшие результаты","search.none":"По запросу «{q}» ничего не найдено. Попробуйте «животное», «яйцо» или «отчёт».","start.label":"Начните здесь","kit.objective.eyebrow":"Начните здесь","kit.objective.more":"Прочитать о цели","kit.objective.kicker":"Зачем мы проводим это обучение","kit.objective.photo":"Смотритель кормит небольшое животное в его вольере","kit.platform.eyebrow":"Платформа","kit.platform.more":"Подробнее об Antz","kit.platform.why":"Зачем использовать это приложение","kit.platform.photo":"Рука держит телефон с открытым приложением Antz Systems","kit.start.eyebrow":"Порядок обучения","kit.start.more":"Начать руководство","kit.start.features":"Функции","day.title":"Как проходит ваш первый день в Antz","day.lede":"Четыре шага ведут вашу команду от первого входа до повседневной работы.","day.1":"Войдите в своё рабочее пространство","day.2":"Освойтесь в интерфейсе","day.3":"Настройте основные справочники","day.4":"Предоставьте всем нужный доступ","day.4.desc":"Создайте роли, соответствующие вашей организации, и включайте разрешения по модулям, чтобы каждый видел то, что нужно для его работы.","modules.eyebrow":"Что внутри","modules.title":"Обзор модулей","modules.lede":"Нажмите на любую карточку, чтобы открыть руководство со всеми функциями и экранами.","modules.filter":"Фильтр модулей по направлению","modules.all":"Все","modules.count":"Модулей: {n}","modules.features":"Функций: {n}","spot.tag":"Избранный рабочий процесс","spot.link":"Подробнее: {x}","cta.title":"Застряли на задаче?","cta.text":"В этом руководстве для каждого модуля описаны функции и показаны настоящие экраны. Продолжите с того места, где остановились, или напишите нам — мы поможем.","cta.back":"Вернуться к модулям","cta.or":"Есть вопросы? Пишите на {email}","faq.eyebrow":"Вопросы и ответы","faq.title":"Вопросы, которые команды задают первыми","faq.q1":"Что такое Antz?","faq.q2":"Работает ли система на телефонах и компьютерах?","faq.a2":"Да. Мобильное приложение охватывает работу на местах: заметки, лечение, перемещения и учёт яиц. Веб-приложение охватывает работу за столом: больничную систему, настройку инкубаторных, отчёты и аптечные запасы. Обновления появляются в реальном времени на телефоне, планшете и компьютере.","faq.q3":"Можно ли управлять тем, кто что видит?","faq.a3":"Да. Доступ основан на ролях. Вы создаёте роли, принятые в вашей организации, например «Зоолог», и включаете разрешения по модулям.","faq.q4":"У нас несколько площадок. Это поддерживается?","faq.a4":"Antz хранит данные всех площадок и отделов в одном месте. Содержание животных организовано по площадкам, секциям и вольерам, а перемещения между площадками проходят согласование и выпуск службой безопасности.","faq.q5":"С чего начать?","faq.a5":"Начните с руководства «Начало работы», затем откройте модули, которые использует ваша роль. Если что-то непонятно, напишите на hello@antz.systems.","pager.prev":"Назад","pager.next":"Далее","pager.modules":"Обзор модулей","pager.pages":"Предыдущая и следующая страница","pager.moduleNav":"Предыдущий и следующий модуль","mod.tabs":"Направления и модули","mod.features":"Функции","mod.hintClick":"Нажмите на функцию, чтобы открыть её экран","mod.hintTap":"Коснитесь функции, чтобы открыть её экран","mod.soon":"Экраны для этого модуля скоро появятся","mod.zoom":"Коснитесь экрана, чтобы увеличить","win.prev":"Предыдущая функция","win.next":"Следующая функция","win.close":"Закрыть","win.count":"Функция {i} из {n}","win.soon":"Экран скоро появится","gal.label":"Экраны: {x}","gal.close":"Закрыть галерею","gal.screen":"Экран {i}","gal.hint":"Сведите пальцы или коснитесь дважды для увеличения · Проведите для просмотра"},"tracks":{"records":{"label":"Записи и общение","desc":"Самые простые и часто используемые разделы: заметки, чат и настройка пользователей."},"animal":{"label":"Учёт и перемещение животных","desc":"Коллекция, содержание и каждое перемещение животного по зоопарку."},"medical":{"label":"Медицина и лечение","desc":"Записи, назначения, лечение и больничная информационная система."},"mortality":{"label":"Падёж и жизненный цикл","desc":"Падёж, вскрытие и управление жизненным циклом яиц."},"operations":{"label":"Операции и контроль","desc":"Объявления, служба поддержки, безопасность, отчётность и соответствие требованиям."}},"modules":{"objective-of-this-kit":{"title":"Цель этого комплекта","intro":"У обучения четыре задачи: дать каждому сотруднику уверенность в повседневной работе, обеспечить внедрение платформы во всех ролях, выявить пробелы, чтобы мы могли улучшаться, и стандартизировать ведение записей на всех площадках.","features":[{"title":"Развитие навыков","desc":"Расширение знаний сотрудников и практических навыков, необходимых для эффективной работы зоопарка, ухода за животными и уверенного использования платформы Antz.","alt":""},{"title":"Внедрение системы","desc":"Знакомство пользователей со всеми модулями приложения и формирование уверенности в выполнении основных действий — записи, проверки и согласования — без контроля со стороны.","alt":""},{"title":"Постоянное улучшение","desc":"Выявление пробелов, прояснение сомнений и обучение на основе обратной связи для постепенного совершенствования рабочих процессов и поведения модулей.","alt":""},{"title":"Стандартизация","desc":"Единые протоколы для всех команд и площадок, одинаковое поведение модулей «Заявки», «Падёж», «Яйца» и «Рацион», чтобы все записи читались одинаково.","alt":""}]},"what-is-antz-systems":{"title":"Что такое Antz Systems?","intro":"Antz — это универсальная платформа для учёта животных, повседневной работы и командного взаимодействия. Она объединяет данные всех площадок и отделов, чтобы каждое действие было задокументировано, прозрачно и отслеживаемо.","features":[{"title":"Лучше записи — лучше уход","desc":"Каждая деталь точна, доступна, снабжена отметкой времени и привязана к нужному животному.","alt":""},{"title":"Простая командная работа","desc":"Никаких разрывов между ветеринарами, смотрителями и руководителями — все работают с одной записью.","alt":""},{"title":"Безопасность по умолчанию","desc":"Доступ на основе ролей защищает конфиденциальные данные и согласует права с организационной структурой.","alt":""},{"title":"Решения под рукой","desc":"Более быстрая отчётность и аналитика, готовая к проверкам, без электронных таблиц.","alt":""},{"title":"Работа без бумаги","desc":"Меньше ошибок при переписывании и экономия времени в каждую смену.","alt":""},{"title":"Обновления в реальном времени","desc":"Актуальная информация в любое время и в любом месте — на телефоне, планшете и компьютере.","alt":""}],"shots":{"assets/shots/app-welcome-c.jpg":"Экран приветствия приложения Antz Systems: хорошие данные + полезные выводы = здоровые животные."}},"getting-started":{"title":"Начало работы","intro":"Руководство «Начало работы» объясняет назначение приложения и проводит новых пользователей через основные шаги: настройку профиля, знакомство с ключевыми функциями и эффективную навигацию по платформе.","features":[{"title":"Доступ и рабочие пространства","desc":"Безопасно войдите в систему и откройте назначенную вам рабочую среду.","alt":"Главный экран Antz Systems: строка поиска, «Ожидает введения», аналитика «В этом месяце» с рождаемостью и падежом, карточка объявления"},{"title":"Навигация и интерфейс","desc":"Используйте ленту на главном экране для обновлений, ярлыки быстрого перехода и нижнюю панель для основных инструментов.","alt":""},{"title":"Ожидает вскрытия / введения / размещения","desc":"Животные, ожидающие вскрытия, оформления документов, а также последующего размещения или утилизации до окончательного закрытия записей.","alt":""},{"title":"Основные настройки и модули","desc":"Настройте основные справочники и изучите такие модули, как «Медицинские записи», «Содержание», «Яйца», «Рацион» и «Управление животными».","alt":""},{"title":"Персонализация","desc":"Управляйте заметками, обновляйте профиль и настраивайте язык.","alt":""},{"title":"Разрешения","desc":"Разберитесь в уровнях доступа, необходимых для безопасной работы.","alt":""}]},"notes-module":{"title":"Модуль «Заметки»","intro":"Модуль «Заметки» централизует записи о ежедневных обновлениях, наблюдениях и происшествиях, связанных с животными, вольерами и работой. Он обеспечивает структурированные записи с отметкой времени, слаженную работу команды, быстрый поиск с помощью фильтров и тегов, а также помогает поддерживать единообразный уход, рано выявлять проблемы и соблюдать требования.","summary":"Централизует записи о ежедневных обновлениях, наблюдениях и происшествиях, связанных с животными, вольерами и работой","features":[{"title":"Добавление и просмотр заметок","desc":"Создавайте новые заметки и просматривайте свои заметки и заметки других уполномоченных пользователей.","alt":"Форма новой заметки: тип заметки, текст, уведомление участников, объект, вложения, приоритет"},{"title":"Изменение, прослушивание и удаление","desc":"Изменяйте, прослушивайте в аудиоформате или удаляйте заметки в соответствии с назначенными разрешениями.","alt":"Подробности заметки: медицинская, болен, тигр AID 425990, с кнопками изменения и закладки"},{"title":"Приоритет","desc":"Укажите уровень срочности, чтобы нужные люди увидели заметку первыми.","alt":"Подробности заметки с флажком приоритета в правом верхнем углу"},{"title":"Тип заметки и привязка","desc":"Классифицируйте заметки, привязывайте их к животным, вольерам или секциям и прикрепляйте документы.","alt":"Подробности заметки с карточкой привязанного животного, тигр AID 425990"},{"title":"Видимость","desc":"Заметки автоматически появляются на страницах соответствующего животного, площадки или секции.","alt":"Вкладка «Заметки» на странице площадки: заметка о гигиене на площадке Central Reserve Kingdom"},{"title":"Уведомления и совместная работа","desc":"Уведомляйте отмеченных участников; отметки «нравится» и комментарии помогают держать обсуждение в фокусе.","alt":"Заметка с отметкой «нравится», отмеченный участник Dr. Cloomy Fernandes, 1 комментарий"},{"title":"Фильтры и поиск","desc":"Фильтруйте по ключевым словам, тегам, автору или привязанному объекту.","alt":"Список заметок с вкладками «Мои заметки» / «Все заметки» и фильтрами"}]},"user-management":{"title":"Управление пользователями","intro":"Модуль пользователей обеспечивает безопасное централизованное управление учётными записями, ролями и разрешениями. Он упрощает подключение новых пользователей, обеспечивает безопасность данных и согласует права доступа с ролями в организации, ведя подробный журнал действий для подотчётности.","summary":"Безопасное централизованное управление учётными записями, ролями и разрешениями","features":[{"title":"Создание и управление профилями","desc":"Управляйте именем, контактами, табельным номером, датой рождения, группой крови.","alt":"Форма основной информации нового пользователя: имя, имя пользователя, эл. почта, пароль, мобильный телефон, табельный номер"},{"title":"Роли и разрешения","desc":"Назначайте роли и управляйте правами доступа на уровне модулей.","alt":"Изменение разрешений: роль «Ветеринар» с флажками доступа к модулям"},{"title":"Контроль доступа","desc":"Ограничивайте доступ по площадке/секции, активируйте учётные записи, настраивайте автоматический выход.","alt":"Профиль пользователя с меню «Деактивировать», «Сбросить пароль», «Сбросить код доступа»"},{"title":"Вход и восстановление","desc":"Безопасный вход с восстановлением через одноразовый код по SMS или WhatsApp.","alt":"Экран сброса / восстановления пароля с полем для имени пользователя или эл. почты"},{"title":"Отслеживание активности","desc":"Просматривайте время последнего входа, сведения об устройствах и отключайте устройства.","alt":"Вкладка «Журнал» в профиле пользователя: журнал действий со временем последней активности"},{"title":"Дополнительные сведения","desc":"Записывайте образование, опыт работы и загружайте документы, удостоверяющие личность.","alt":"Вкладка «Документы» в профиле пользователя: карта Aadhaar с вложением"}]},"collection":{"title":"Коллекция","intro":"Модуль «Коллекция» предназначен для управления всеми аспектами коллекции животных учреждения и их документирования. Это центральное место для учёта видов, отслеживания отдельных особей и ведения точной таксономической истории.","summary":"Управление всеми аспектами коллекции животных учреждения и их документирование: учёт видов, отслеживание особей и точная таксономическая история","features":[{"title":"Обзор коллекции","desc":"Таксономия, численность по полу, количество поступлений и рождений, с поиском.","alt":"Обзор коллекций: показатели по видам и численности, поступления и рождения, а также таксономические классы с количеством"},{"title":"Управление видом","desc":"Численность, морфы, медицина, рацион, падёж и статус вскрытия.","alt":"Подробности вида «Тигр»: численность, площадки, секции, вольеры"},{"title":"Групповая оценка","desc":"Ввод данных для группы с последовательным переходом и фильтрами.","alt":"Список оценок вида с упитанностью каждого животного"}]},"housing":{"title":"Содержание","intro":"Модуль «Содержание» упорядочивает места обитания животных по площадкам, секциям и вольерам, чтобы у каждого животного было известное место, а каждое изменение отслеживалось. Доступ на каждом уровне определяется разрешениями.","summary":"Упорядочивает места обитания животных по площадкам, секциям и вольерам, чтобы у каждого животного было известное место, а каждое изменение отслеживалось","features":[{"title":"Управление площадками","desc":"Добавляйте и изменяйте площадки с разрешениями на основе ролей для безопасного упорядоченного доступа.","alt":"Подробности площадки Wildlife Zoological Park: количество видов, животных и секций, список вольеров"},{"title":"Управление секциями","desc":"Добавляйте и изменяйте секции зоопарка с контролем на основе разрешений для безопасного администрирования.","alt":"Подробности секции Animal Kingdom: количество видов, животных и вольеров, список вольеров"},{"title":"Управление вольерами","desc":"Добавляйте и изменяйте вольеры и следите за каждым из них для эффективного контроля животных и данных.","alt":"Список вольеров: Gentle Giants, Herbivores, The Tiger Trail с количеством животных"}]},"animal-management":{"title":"Управление животными","intro":"Модуль «Животные» собирает все записи о животных в одном месте — активных, переданных, пропавших или удалённых, — с профилями, процессами поступления и удобным расположением по вкладкам.","summary":"Собирает все записи о животных в одном месте","features":[{"title":"Поиск животных","desc":"Добавляйте новых животных с помощью пошаговых процессов, связанных с содержанием, рационом и медициной.","alt":"Список животных с количеством: все животные 2828, переданные 11, удалённые 27, пропавшие/сбежавшие 8"},{"title":"Недавно добавленные","desc":"Новые животные в системе, вверху ленты.","alt":"Список недавно добавленных: толстый лори, африканский саванный слон, тигр, гребнистый крокодил, шлемоносный казуар"},{"title":"Все животные","desc":"Полная база данных с поиском, фильтрами и экспортом.","alt":"Список всех животных: европейский кролик, шлемоносный казуар, обыкновенный бегемот, тигр, азиатский слон"},{"title":"Переданные","desc":"Животные, перемещённые между площадками или вольерами, с полной историей происхождения.","alt":"Список переданных животных: тигр, лев, толстый лори, барибал, лев"},{"title":"Удалённые","desc":"Записи об удалённых животных, сохраняемые для аудита и возможности восстановления.","alt":"Список удалённых животных"},{"title":"Пропавшие / сбежавшие","desc":"Животные, отмеченные как пропавшие или сбежавшие, со ссылкой на отчёт о происшествии.","alt":"Список пропавших/сбежавших животных: барибал, шлемоносный казуар, гребнистый крокодил, обыкновенный бегемот, тигр"}]},"tags-hub":{"title":"Центр тегов","intro":"Модуль «Центр тегов» помогает упорядочивать и классифицировать различные объекты (площадки, секции, вольеры, животных) на платформе ANTZ с помощью настраиваемых меток по их текущему статусу, назначению или любой собственной классификации.","summary":"Помогает упорядочивать и классифицировать объекты (площадки, секции, вольеры, животных) на платформе ANTZ с помощью настраиваемых меток по статусу, назначению или собственной классификации","features":[{"title":"Типы тегов — публичные, личные, системные","desc":"Упорядочивайте и классифицируйте объекты с помощью публичных, личных и системных тегов.","alt":"Мой центр тегов: поиск, количество тегов (всего, системные, публичные, личные) и значки публичных и личных тегов"},{"title":"Поиск и фильтры","desc":"Быстро находите теги с помощью поиска и фильтров.","alt":"Мой центр тегов: поиск, количество тегов (всего, системные, публичные, личные) и значки публичных и личных тегов"},{"title":"Создание тегов","desc":"Создавайте новые публичные или личные теги в соответствии с вашими потребностями.","alt":"Создание нового тега: название, категория, роли для уведомления, заметки и кнопка «Создать тег»"},{"title":"Изменение и удаление тегов","desc":"Изменяйте название, цвет или видимость личных тегов либо окончательно удаляйте ненужные теги.","alt":"Панель сведений о теге: категория, тип, автор, заметки, отмеченные объекты, с действиями «Изменить» и «Удалить»"},{"title":"Назначение публичных и личных тегов","desc":"Присваивайте теги площадкам, секциям, вольерам или животным для удобной организации.","alt":"Вкладка «Теги» в профиле животного: публичные и личные теги, разделы «Мои теги» и «Теги других», а также кнопка + для добавления тега"},{"title":"Снятие назначенных тегов","desc":"Снимайте теги с площадок, секций, вольеров или животных, когда это необходимо.","alt":"Подтверждение снятия тега: «Вы уверены, что хотите снять эти теги с площадки?» — «Отмена» или «Снять»"},{"title":"Видимость","desc":"Определяйте, остаются ли личные теги только вашими или видны всем пользователям.","alt":"Сведения о личном теге: тип «Личный (виден всем)» с переключателем «Сделать тег видимым для всех»"},{"title":"Отмеченные объекты","desc":"Просматривайте все площадки, секции, вольеры, виды и животных, связанных с выбранным тегом.","alt":"Вкладка «Объекты» тега «Пора провести дегельминтизацию»: 12 отмеченных объектов, список вольеров, секций, видов и животных с поиском"}]},"animal-transfer":{"title":"Перемещение животных","intro":"Учитывает все перемещения животных внутри организации и за её пределы и управляет ими, отслеживая заявки, согласования и размещение для безопасного и хорошо задокументированного перемещения.","summary":"Учитывает все перемещения животных внутри организации и за её пределы и управляет ими","features":[{"title":"Типы перемещений","desc":"Внутренние, между площадками и внешние перемещения.","alt":"Окно выбора типа перемещения: внутреннее, между площадками и внешнее"},{"title":"Согласование","desc":"Разрешение от назначенных ответственных лиц площадки.","alt":"Перемещение между площадками ожидает одобрения, с кнопками «Одобрить» и «Отклонить»"},{"title":"Отмена / отклонение","desc":"Отменяйте или отклоняйте заявки и при необходимости создавайте их заново.","alt":"Пункт «Отменить перемещение» в меню перемещения"},{"title":"Пропуск службой безопасности (вход / выход)","desc":"Контролируемый вход и выход при перемещениях между площадками и внешних перемещениях.","alt":"Ожидается проверка охраны, с действием «Выезд через охрану»"},{"title":"Размещение","desc":"По прибытии разместите животное в вольере и уведомите сотрудников.","alt":"Статус «Животные получены», с действием «Распределить по вольерам»"},{"title":"Журнал перемещений","desc":"Полная история статусов с отметками времени и пользователями.","alt":"Хронология перемещения, завершающаяся статусом «Перемещение завершено»"}]},"approvals":{"title":"Согласования","intro":"Управляет заявками на перемещение животных и отслеживает их, показывая ожидающие, согласованные и отклонённые заявки. Упрощает процесс рассмотрения, обеспечивает надлежащее разрешение и сохраняет прозрачную запись решений о перемещении для подотчётности и соблюдения требований.","summary":"Управляет заявками на перемещение животных и отслеживает их, показывая ожидающие, согласованные и отклонённые заявки","features":[{"title":"Отслеживание статуса","desc":"Ожидает согласования, согласовано, отклонено, разрешён выход/вход, размещено.","alt":"Список согласований перемещений со значками статуса"},{"title":"Рассмотрение заявки","desc":"Просматривайте все подробности перед согласованием.","alt":"Подробности заявки на перемещение для рассмотрения"},{"title":"Согласование / отклонение","desc":"Одобряйте или отклоняйте заявки с надлежащим обоснованием.","alt":"Подробности заявки на перемещение с кнопками «Согласовать» и «Отклонить»"},{"title":"Сброс согласования","desc":"Повторно откройте или обновите ранее согласованную заявку.","alt":"Согласованное перемещение с вариантом «Сбросить согласование»"},{"title":"Отмена перемещения","desc":"Отменяйте до или после согласования с записью причины.","alt":"Подробности заявки с вариантом «Отменить перемещение»"}]},"missing-escaped-animal":{"title":"Пропавшее / сбежавшее животное","intro":"Позволяет быстро сообщать о пропавших или сбежавших животных, отслеживать такие случаи и закрывать их. Записи с отметкой времени привязываются к профилям животных для подотчётности и согласованных действий службы безопасности, ветеринаров и руководства.","summary":"Быстрое сообщение, отслеживание и закрытие случаев пропажи или побега животных","features":[{"title":"Сообщение о происшествии и вложения","desc":"Записывайте подробности и действия, загружайте фото или видео.","alt":"Форма сообщения о сбежавших/пропавших животных"},{"title":"Изменение отчёта","desc":"Обновляйте отчёт о происшествии по мере развития событий.","alt":"Хронология происшествия, животное пропало"},{"title":"Сообщение о возвращении","desc":"Записывайте подробности возвращения животного и отмечайте исправления.","alt":"Форма сообщения о найденном животном"},{"title":"Журнал событий и отслеживаемость","desc":"Каждое действие записывается по порядку в хронологии животного.","alt":"Меню с вариантом «Ошибочное сообщение о пропаже»"},{"title":"Видимость","desc":"Отметка о пропаже в профиле животного.","alt":"Профиль животного со значком пропажи и QR-кодом"}]},"medical-records":{"title":"Медицинские записи","intro":"Медицинский модуль помогает записывать, отслеживать и вести сведения о здоровье животных, включая диагнозы, назначения и лечение. Он обеспечивает своевременную помощь, упорядоченную историю болезни и координацию между ветеринарными командами ради благополучия животных.","summary":"Помогает записывать, отслеживать и вести сведения о здоровье животных","features":[{"title":"Создание записей","desc":"Несколько способов добавить индивидуальные, пакетные, групповые, плановые (вакцинация, дегельминтизация, добавки) или прямые (введение, назначение, вакцинация, дегельминтизация, добавки) записи и заявки в лабораторию с точной датой и временем.","alt":"Меню создания записи: индивидуальная, групповая, пакетная медицинская запись, сводная заявка в лабораторию, прямое введение, назначение, вакцинация, дегельминтизация, добавки"},{"title":"Обзор записи","desc":"Краткая сводка со сведениями о враче и профилем животного для удобства.","alt":"Обзор медицинской записи MED-09501: врач, профиль животного, тип случая и симптомы"},{"title":"Закладка, изменение, удаление, загрузка","desc":"Изменяйте или удаляйте записи; загруженные отчёты отправляются на зарегистрированный адрес эл. почты.","alt":"Медицинская запись MED-08805 со значками закладки, изменения и дополнительных действий"},{"title":"Хронология медицинского журнала","desc":"Хронологический журнал всех добавлений и изменений с полной отслеживаемостью.","alt":"Медицинский журнал: хронологический журнал действий с медицинскими записями и отметками времени"},{"title":"Переназначение записей","desc":"Врачи могут переназначить на себя записи, изначально созданные другим ветеринаром.","alt":"Подтверждение переназначения: «Переназначить эту медицинскую запись на себя?» Да / Нет"}]},"symptoms-clinical-assessment-prescription":{"title":"Симптомы, клиническая оценка и назначения","intro":"Функция «Симптомы, клиническая оценка и назначения» даёт аналитику по записанным симптомам, диагнозам и назначенному лечению, помогая отслеживать тенденции в состоянии здоровья и принимать обоснованные клинические решения.","summary":"Аналитика по записанным симптомам, диагнозам и назначенному лечению для отслеживания тенденций и обоснованных клинических решений","features":[{"title":"Тенденции симптомов","desc":"Анализируйте наиболее часто записываемые симптомы у разных видов и отслеживайте их появление во времени.","alt":"Аналитика симптомов: 7 видов, 7 по симптомам, рейтинг во главе с «Нарушение помёта», «Нарушение позы», «Нарушение линьки»"},{"title":"Аналитика клинических оценок","desc":"Следите за клиническими оценками животных и выявляйте наиболее часто записываемые диагнозы или состояния.","alt":"Аналитика клинических оценок: 20 видов, 35 оценок, во главе с болезнью печени, кариесом, желудочно-кишечными проблемами"},{"title":"Аналитика назначений","desc":"Просматривайте часто назначаемые препараты и схемы лечения по видам и случаям.","alt":"Аналитика назначений: 7 видов, 7 назначений, во главе с Aculife, Fluvac Innovator, Dolo 650"},{"title":"Фильтры и поиск","desc":"Уточняйте данные по периоду, площадке, виду и другим критериям.","alt":"Фильтр по периоду: сегодня, вчера, последние 7 дней, этот месяц, последние 3 месяца, последние 6 месяцев, все данные"}]},"administer-medicine":{"title":"Введение препаратов","intro":"Модуль «Введение» дополняет медицинские записи, превращая назначения в практические процессы лечения. Он позволяет оказывать помощь в реальном времени отдельным животным или группам — в полевых условиях или в больнице.","summary":"Дополняет медицинские записи, превращая назначения в практические процессы лечения","features":[{"title":"Быстрый ввод","desc":"Создайте запись о прямом введении на выбранную дату без полной медицинской записи.","alt":"Экран введения: лента дат, вкладки «Животные» / «Групповые записи», плитки статусов «Введено» / «Пропущено» / «Прекращено» / «Ожидает», выделена кнопка быстрого ввода «плюс»"},{"title":"Поиск и фильтры","desc":"Быстро находите записи и сужайте список по дате, объекту, виду, контролируемому веществу.","alt":"Экран введения с выделенными поиском, фильтрами, выбором месяца и списком «Все записи»"},{"title":"Отслеживание статуса","desc":"Просматривайте лечение по датам на четырёх вкладках: «Ожидает», «Введено», «Пропущено», «Прекращено».","alt":"Экран введения с выделенными вкладками статусов «Введено», «Пропущено», «Прекращено», «Ожидает»"},{"title":"Массовые действия","desc":"Выберите несколько записей, чтобы сразу отметить введение или пропуск препаратов.","alt":"Экран введения с выделенными кнопками «Выбрать все» и «Ввести» после выбора записей"},{"title":"Подробности назначения","desc":"Вся информация — дозировка, номер партии, связанное животное — прямо в момент введения.","alt":"Экран назначения с выделенными временем, частотой, продолжительностью и способом введения"},{"title":"Ввод отдельной дозы","desc":"Записывайте отдельные дозы со временем, номером партии и заметками.","alt":"Экран введения с выделенной карточкой группы для отдельной дозы и её флажком"},{"title":"Обзор на главном экране","desc":"Количество ожидающих процедур видно прямо на главном экране, чтобы действовать быстрее.","alt":"Экран «Ожидающие введения»: всего 847 ожидающих доз по животным, препаратам и контролируемым веществам, с разбивкой по площадкам"}],"shots":{"assets/shots/p20-bulk.png":"Массовые действия при введении: «Выбрать все», выбранная запись животного и кнопки «Пропущено» / «Ввести»","assets/shots/p20-prescription.png":"Подробности назначения: ID случая, время, частота, продолжительность, способ введения, связанное животное и график доз"}},"vaccination":{"title":"Вакцинация","intro":"Модуль «Вакцинация» охватывает полный цикл вакцинации животных — от планирования и прямого введения до отслеживания предстоящих, ожидающих, пропущенных и выполненных прививок. Он обеспечивает своевременное лечение, точную запись дозировки и полную отслеживаемость для профилактики заболеваний и соблюдения клинических требований.","summary":"Полный цикл вакцинации животных — от планирования и прямого введения до отслеживания предстоящих, ожидающих, пропущенных и выполненных прививок","features":[{"title":"Представления по статусу","desc":"Прививки разделены на предстоящие, ожидающие, пропущенные, выполненные и остановленные для удобного контроля.","alt":"Меню вакцинации: предстоящие, ожидающие, выполненные, пропущенные, прекращённые, прямое введение, запланировать вакцинацию"},{"title":"Управление вакцинацией","desc":"Запланируйте вакцинацию или сразу запишите введённую вакцину с указанием дат и сведений о препарате.","alt":"Планирование вакцинации с выбранными животными, назначением и клиническими заметками"},{"title":"Запись введения","desc":"Фиксирует дозировку, номер партии, способ введения, заметки и при необходимости повторный осмотр.","alt":"Подробности выполненной вакцинации с ID случая и номером партии"},{"title":"Ожидающие и предстоящие","desc":"Показывает все запланированные прививки по дате и площадке, чтобы не пропустить процедуры.","alt":"Ожидающие прививки, сгруппированные по видам"},{"title":"Пропуск и прекращение","desc":"Откладывайте или прекращайте вакцинацию с обязательным указанием причины и даты повторного осмотра.","alt":"Подробности ожидающей вакцинации с действиями «Ввести» и «Пропустить»"},{"title":"Доступ через животное","desc":"Записи о вакцинации можно просматривать из разделов «Животные», «Содержание» или «Медицинские записи».","alt":"Вкладка «Медицина» в профиле животного с ожидающими, предстоящими и выполненными прививками"}]},"deworming":{"title":"Дегельминтизация","intro":"Модуль «Дегельминтизация» обеспечивает систематическую запись и контроль противопаразитарных обработок, своевременное введение препаратов, надлежащее документирование и чёткое отслеживание каждой дегельминтизации для каждого животного.","summary":"Систематическая запись и контроль противопаразитарных обработок","features":[{"title":"Представления по статусу","desc":"Дегельминтизация разделена на предстоящие, ожидающие, пропущенные, выполненные и остановленные для удобного контроля.","alt":"Меню дегельминтизации: предстоящие, ожидающие, выполненные, пропущенные, прекращённые, прямое введение, запланировать дегельминтизацию"},{"title":"Управление дегельминтизацией","desc":"Запланируйте курс или сразу запишите введённый препарат с указанием дат и подробностей.","alt":"Прямая дегельминтизация с выбранным животным, назначением и клиническими заметками"},{"title":"Запись введения","desc":"Фиксирует дозировку, номер партии, способ введения, заметки и при необходимости повторный осмотр.","alt":"Добавление препарата: тип дозы, количество, способ введения, повторный осмотр и номер партии"},{"title":"Ожидающие и предстоящие","desc":"Все запланированные дегельминтизации по дате и площадке, чтобы не пропустить процедуры.","alt":"Ожидающие дегельминтизации, сгруппированные по видам"},{"title":"Пропуск и прекращение","desc":"Откладывайте или прекращайте с обязательным указанием причины и даты повторного осмотра.","alt":"Пропуск дегельминтизации: перенос или прекращение с причиной и вопросом о побочных эффектах"},{"title":"Доступ через животное","desc":"Доступно из разделов «Животные», «Содержание» или «Медицинские записи».","alt":"Вкладка «Медицина» в профиле животного с ожидающими, предстоящими и выполненными дегельминтизациями"}]},"supplements":{"title":"Добавки","intro":"Модуль «Добавки» обеспечивает систематическую запись и контроль программ пищевых и кормовых добавок, своевременную дачу, надлежащее документирование и чёткое отслеживание каждой добавки, полученной каждым животным.","summary":"Систематическая запись и контроль программ пищевых и кормовых добавок","features":[{"title":"Представления по статусу","desc":"Добавки разделены на предстоящие, ожидающие, пропущенные, выполненные и остановленные для удобного контроля.","alt":"Меню добавок: предстоящие, ожидающие, выполненные, пропущенные, прекращённые, прямое введение, запланировать добавки"},{"title":"Управление добавками","desc":"Запланируйте или сразу запишите данные добавки с указанием дат и подробностей.","alt":"Прямая дача добавок с выбранным животным, назначением и клиническими заметками"},{"title":"Запись введения","desc":"Фиксирует дозировку, номер партии, способ введения, заметки и при необходимости повторный осмотр.","alt":"Добавление добавок: тип дозы, количество, способ введения, повторный осмотр и номер партии"},{"title":"Ожидающие и предстоящие","desc":"Все запланированные добавки по дате и площадке, чтобы не пропустить дачу.","alt":"Ожидающие добавки, сгруппированные по видам"},{"title":"Пропуск и прекращение","desc":"Откладывайте или прекращайте с обязательным указанием причины и даты повторного осмотра.","alt":"Пропуск добавок: перенос или прекращение с причиной и датой повторного осмотра"},{"title":"Доступ через животное","desc":"Записи доступны из разделов «Животные», «Содержание» или «Медицинские записи».","alt":"Вкладка «Медицина» в профиле животного с ожидающими, предстоящими и выполненными добавками"}]},"hospital-information-management-system-app":{"title":"Больничная информационная система (App)","intro":"В приложении сотрудники оформляют перевод животных в больницу и безопасно перемещают пациентов, указывая медицинский ID, тип визита, цель, вложения, с пропуском службой безопасности на входе и выходе на площадке и в больнице.","summary":"Сотрудники оформляют перевод животных в больницу и безопасно перемещают пациентов","features":[{"title":"Заявки на перевод","desc":"Оформляйте запросы на госпитализацию животных с площадки в больницу с медицинским ID, типом визита, целью и вложениями.","alt":"Форма госпитализации животного: выбранное животное, медицинский ID (создать новый), поля больницы и типа визита, «Отправить»"},{"title":"Статус перевода","desc":"Отслеживайте каждый перевод по этапам на уровне площадки: «Ожидает», «В пути», «Принято», «Отменено» и «Отклонено».","alt":"Вкладка «Перевод в больницу» в профиле площадки: вкладки «В пути», «Принятые» и «Отменённые», с запросами вроде HT29-00069, ожидающими принятия"},{"title":"Пропуск службой безопасности (вход / выход)","desc":"Контролируемое перемещение пациентов с пропуском службой безопасности на входе и выходе на площадке и в больнице.","alt":"Перевод HT29-00068: ожидается выезд через охрану, с кнопкой «Въезд через охрану»"},{"title":"Просмотр выписок","desc":"Открывайте выписные эпикризы и историю госпитализаций прямо из приложения.","alt":"Медицинская запись MED29-18889 гребнистого крокодила: тип случая и вложение Discharge_Summary.pdf, добавленное ветеринаром"}]},"hospital-information-management-system-web":{"title":"Больничная информационная система (Web)","intro":"В веб-консоли клинические команды принимают и сортируют поступающих пациентов, наблюдают за стационарными и амбулаторными пациентами, записывают лечение и выписывают животных — с полной медицинской отслеживаемостью и отчётами для загрузки.","summary":"Клинические команды принимают и сортируют поступающих пациентов, наблюдают за стационарными и амбулаторными пациентами, записывают лечение и выписывают животных","features":[{"title":"Приём и сортировка","desc":"Принимайте или отклоняйте случаи с назначением врача, палаты и места в зависимости от требуемого лечения.","alt":"Форма приёма пациента: выбранное животное, цель визита, тип лечения амбулаторно / стационарно, состояние здоровья, «Отклонить» и «Принять»"},{"title":"Наблюдение за стационарными / амбулаторными пациентами","desc":"Настраивайте и записывайте плановые показатели жизнедеятельности и наблюдения с изменяемой хронологией.","alt":"Список поступающих пациентов: вкладки «Ожидают» и «Отклонены» с животными и целью визита"},{"title":"Клинические записи и записи о лечении","desc":"Ведите симптомы, клинические заметки, назначения, анестезию, операции и другое лечение в одном месте.","alt":"Стационарная запись MED29-17409: сведения о поступлении и вкладки «Симптомы» / «Клиническая оценка» / «Назначение»"},{"title":"Выписка","desc":"Выписывайте животных обратно в вольер или записывайте падёж с заявкой на вскрытие и вложениями.","alt":"Вкладка «Выписка»: причина поступления, тип выписки «Падёж» / «Перевод в вольер», «Выписать животное»"},{"title":"Отчёты для загрузки","desc":"Открывайте выписные эпикризы, сведения о текущей госпитализации и историю прошлых визитов.","alt":"Список выписанных пациентов с длительностью, типом визита, главным ветеринаром и действием загрузки"}]},"mortality":{"title":"Падёж","intro":"Модуль «Падёж» позволяет быстро и точно записывать гибель животных, вести сведения о вскрытии и хранить доказательства в одном месте. Он повышает прозрачность, ускоряет принятие решений, обеспечивает соблюдение требований и помогает лучше следить за благополучием животных.","summary":"Быстрая и точная запись гибели животных, сведения о вскрытии и доказательства в одном месте","features":[{"title":"Панель падежа","desc":"Итоги по случаям гибели, затронутым видам и причинам.","alt":"Панель смертности: 49 животных, 16 видов и 6 причин, с выделенными показателями"},{"title":"Списки в нескольких представлениях","desc":"Записи по животному, виду или причине со ссылками на профили.","alt":"Записи о падеже по видам, с количеством по полу"},{"title":"Расширенный поиск и фильтры","desc":"Поиск по виду, причине, месту, дате или ключевому слову.","alt":"Панель смертности с выделенными полями «Все данные», «Все площадки», поиском и значком фильтра"},{"title":"Записи о павших животных","desc":"Полные сведения о гибели: причина, ID, вольер, площадка, пол.","alt":"Панель смертности с выделенной первой карточкой животного"},{"title":"Изменение записей","desc":"Изменяйте отчёты о падеже после ввода, чтобы они оставались точными.","alt":"Отчёт о падеже с выделенным значком карандаша для редактирования"},{"title":"Отзыв записей","desc":"Отзывайте ошибочные записи, чтобы вернуть животному активный статус.","alt":"Отчёт о падеже с выделенной кнопкой «Отозвать запись о падеже»"},{"title":"Передача туши","desc":"Просматривайте и отслеживайте перемещение туш между местами.","alt":"Список перевозок туш: 3 ожидают, 1 в пути, 8 завершены"}],"shots":{"assets/shots/p27-mortality-4.jpg":"Карточка записи о падеже — изменение и отзыв"}},"necropsy":{"title":"Вскрытие","intro":"Модуль «Вскрытие» документирует патологоанатомические исследования с подробными наблюдениями, находками по органам и медицинскими заключениями. Он обеспечивает точный анализ причины гибели, стандартизирует отчётность, своевременное обращение с тушами и соответствие правовым, аудиторским и ветеринарным требованиям.","summary":"Документирует патологоанатомические исследования с подробными наблюдениями, находками по органам и медицинскими заключениями","features":[{"title":"Поиск и фильтры","desc":"Поиск по животному/виду; фильтры по площадке, дате, приоритету.","alt":"Список вскрытий: «Входящие», «Ожидающие», «Черновик», «Завершённые», с выделенными вкладками «По животным»/«По видам» и строкой поиска"},{"title":"Отслеживание статуса","desc":"Следите за этапами: «Входящие», «Ожидающие», «Черновики» и «Завершённые».","alt":"Список вскрытий со вкладками статусов «Входящие», «Ожидающие», «Черновик», «Завершённые», выбрана «Ожидающие»"},{"title":"Карточка животного и сведения о заявке","desc":"AID, вид, местонахождение, причина, заявитель, приоритет.","alt":"Список вскрытий с выделенной первой карточкой запроса"},{"title":"Передача туши","desc":"Просматривайте заявки на передачу: «Ожидает принятия», «Получено».","alt":"Перевозки туш: вкладки «Ожидает принятия» и «Получено», с карточками запросов"},{"title":"Подробный просмотр заявки","desc":"Просматривайте полную заявку на вскрытие со сведениями о животном и падеже (причина, состояние туши, заметки), обновляйте записи, сохраняйте черновик или отправляйте после завершения.","alt":"Запрос на вскрытие: отчёт о падеже, предполагаемая причина, состояние туши и статус «Ожидает»"},{"title":"Загрузка отчёта","desc":"Экспортируйте отчёты или черновики в PDF для архива и работы офлайн.","alt":"Отчёт о вскрытии NPS29-00033 с выделенным значком загрузки, пригодность туши и сведения"},{"title":"Хронология","desc":"Каждое действие отслеживается с указанием пользователя и времени.","alt":"История: «Вскрытие завершено», «Черновик удалён», «Сохранено как черновик», у каждого пользователь и время"}]},"fetal-death":{"title":"Гибель плода","intro":"Модуль «Гибель плода» учитывает случаи гибели плода в вольерах, фиксируя причину, время и связанные сведения о животных. Он помогает ветеринарной работе, контролю репродуктивного здоровья, анализу тенденций и улучшению управления популяцией.","summary":"Учёт случаев гибели плода в вольерах","features":[{"title":"Добавление записи о гибели плода","desc":"Записывайте новые случаи: причина, время, родители, сведения о животном.","alt":"Форма добавления гибели плода с вольером, видом, родителем"},{"title":"Поиск и фильтры","desc":"Поиск по ключевому слову; фильтры по площадке, дате, мертворождению или аборту, виду или полу.","alt":"Список случаев гибели плода с поиском и фильтром"},{"title":"Просмотр записей о гибели","desc":"Полные сведения: дней с момента гибели, причина, ID, вольер, площадка, пол.","alt":"Список записей о гибели плода, вкладка «Мертворождение»"},{"title":"Карточка животного","desc":"FID, вид, обнаружение, родители, площадка, пол, кто сообщил.","alt":"Карточка сводки о гибели плода"},{"title":"Изменение записи","desc":"Изменяйте существующую запись из сводки с сохранением журнала аудита.","alt":"Сводка о гибели плода со значком карандаша для изменения"},{"title":"Удаление записи","desc":"Удаляйте запись при необходимости с полным журналом аудита.","alt":"Сводка о гибели плода с вариантом «Удалить гибель плода»"}]},"egg-management-app":{"title":"Управление яйцами — App","intro":"Модуль «Яйца» отслеживает полный жизненный цикл яиц — от кладки до вылупления или передачи в инкубаторную, — обеспечивая точные записи, обновления в реальном времени и полную отслеживаемость для слаженной и подотчётной работы команд гнёзд, инкубаторной и выводковой.","summary":"Отслеживает полный жизненный цикл яиц","features":[{"title":"Панель яиц","desc":"Актуальные данные: в гнёздах, переданы в инкубаторную, отмечены к выбраковке.","alt":"Панель сбора яиц: 66 в гнезде, 76 в инкубаторную, 35 к выбраковке"},{"title":"Ввод яиц (гнездо / инкубаторная)","desc":"Добавляйте яйца с родителями, состоянием, датами, видом, заметками и вложениями.","alt":"Форма добавления яиц с вольером, родителями, местом нахождения яйца"},{"title":"Отслеживание жизненного цикла","desc":"Статус, вес и полная хронология пути яйца.","alt":"Хронология пути яйца: вылупилось, естественная инкубация"},{"title":"Естественная инкубация","desc":"Яйца, насиживаемые в гнёздах: ID, дата сбора, состояние.","alt":"Список яиц в гнезде с записями о павах"},{"title":"Искусственная инкубация","desc":"Яйца в инкубаторной: оценка, перенос в инкубатор, выбраковка или вылупление.","alt":"Список яиц для инкубаторной"},{"title":"Передача яиц","desc":"Отслеживайте площадку, стадию, дату вылупления, вид, ID и пол.","alt":"Переданные яйца — заявки на пакетную передачу"},{"title":"Выбраковка яиц","desc":"Выбраковывайте нежизнеспособные яйца с записью причины и журналом аудита.","alt":"Список яиц к выбраковке"},{"title":"Создание ID животного","desc":"Создайте запись для вылупившихся птенцов, связанную с видом и родителями.","alt":"Вылупившиеся яйца — «Создать ID животного»"}]},"egg-management-web":{"title":"Управление яйцами — Web","intro":"Веб-версия модуля «Управление яйцами» для руководителей и старших сотрудников инкубаторной: настройка инкубаторов, формирование отчётов и отслеживание яиц на каждой стадии жизненного цикла. Полная отслеживаемость, представления с фильтрами и экспортируемые отчёты для проверок и анализа.","summary":"Для руководителей и старших сотрудников инкубаторной: настройка инкубаторов, отчёты и отслеживание яиц на каждой стадии жизненного цикла","features":[{"title":"Настройка инкубаторной и инкубаторов","desc":"Создавайте инкубаторные, привязанные к площадкам, добавляйте помещения, управляйте инкубаторами.","alt":"Список инкубаторных с помещениями, инкубаторами и площадками"},{"title":"Отчёты, фильтры и доступ к данным","desc":"Фильтруйте по площадке, виду, дате или стадии; экспортируйте отчёты.","alt":"Таблица статистики яиц по видам"},{"title":"Список яиц","desc":"Вкладки по статусу: «Получены», «Инкубация», «Вылупились», «Выбракованы», «Все».","alt":"Список яиц с вкладками «Получены», «Инкубация», «Вылупились»"}]},"announcement":{"title":"Объявления","intro":"Модуль «Объявления» — централизованный инструмент для распространения важных новостей и общих уведомлений между командами и площадками. Он поддерживает адресную рассылку, планирование и интерактивное взаимодействие, чтобы нужное сообщение дошло до нужных людей в нужное время.","summary":"Централизованный инструмент для распространения важных новостей и общих уведомлений между командами и площадками","features":[{"title":"Типы объявлений","desc":"Общие и важные, у каждого типа свои правила видимости.","alt":"Список объявлений с вкладками «Все» и «Созданные мной», карточки важных и общих объявлений"},{"title":"Единый список","desc":"Все объявления в одном представлении, ваши отделены от чужих.","alt":"Подробности объявления: Every Move Counts с прикреплённым изображением"},{"title":"Создание объявлений","desc":"Укажите тип, заголовок, видимость; опубликуйте сразу или по расписанию; предварительный просмотр и вложения.","alt":"Подробности объявления: Every necropsy counts, с кнопкой создания"},{"title":"Действия после публикации","desc":"Изменяйте, отменяйте или удаляйте объявления. Уведомления и главная страница делают их видимыми для нужных людей.","alt":"Подробности общего объявления с открытым меню «Изменить», «Отменить», «Удалить»"}]},"helpdesk-module":{"title":"Модуль «Служба поддержки»","intro":"Модуль заявок помогает сотрудникам зоопарка подавать и отслеживать заявки на ресурсы, обслуживание или услуги, обеспечивая подотчётность, быстрое решение и лучшую координацию между отделами. Заменяет электронную почту и бумажные бланки единым проверяемым журналом.","summary":"Помогает сотрудникам зоопарка подавать и отслеживать заявки на ресурсы, обслуживание или услуги, обеспечивая подотчётность, быстрое решение и координацию между отделами","features":[{"title":"Просмотр заявок по статусу","desc":"Ожидает, согласовано, отклонено, отменено, в работе, выполнено.","alt":"Список службы поддержки с вкладками «Ожидает согласования», «Согласовано», «Отклонено», «Отменено»"},{"title":"Управление заявками","desc":"Создавайте, изменяйте, отменяйте или отклоняйте заявки с указанием приоритета.","alt":"Подробности заявки на столярные работы с подрядчиком и сметой"},{"title":"Управление затратами","desc":"Добавляйте, изменяйте, копируйте или удаляйте сметы по каждой позиции.","alt":"Разбивка затрат: позиции «Кровля» и «Древесина»"},{"title":"Выполнение и возврат","desc":"Отмечайте заявки как выполненные или возвращайте их в работу.","alt":"Выполненная заявка с вариантом «Вернуть в работу»"}]},"security":{"title":"Безопасность","intro":"Модуль «Безопасность» управляет разрешениями на уровне площадок и контролирует передачу и выбраковку яиц, а также любые перемещения животных и переводы в больницу, обеспечивая контролируемое перемещение и полную подотчётность: кто, что и когда.","summary":"Управляет разрешениями на уровне площадок и контролирует передачу и выбраковку яиц, перемещения животных и переводы в больницу, обеспечивая полную подотчётность: кто, что и когда","features":[{"title":"Фильтрация","desc":"Фильтруйте записи по статусу — «Показать все», «Ожидает выпуска» или «Выпуск службой безопасности подтверждён» — для целевой проверки.","alt":"Диалог «Фильтр»: «Показать все», «Ожидает выпуска», «Выпуск службой безопасности подтверждён»"},{"title":"Вход и выход","desc":"Уполномоченные сотрудники службы безопасности оформляют вход и выход при передаче яиц, перемещении животных и переводах в больницу.","alt":"Перемещение INT-02997 с кнопкой выпуска службой безопасности"}]},"reports-app":{"title":"Отчёты - App","intro":"Модуль «Отчёты» представляет сгруппированные данные о ключевых событиях с животными под отдельными заголовками для быстрого анализа в дороге.","summary":"Сгруппированные данные о ключевых событиях с животными под отдельными заголовками для быстрого анализа в дороге","features":[{"title":"Фильтры","desc":"Уточняйте отчёты по дате, площадке или виду.","alt":"Отчёт «Ключевые показатели»: фильтр день/неделя/месяц, дата, рождаемость и разбивка по видам"},{"title":"Статистика","desc":"Фильтрация по дате и статистика по категориям: рождаемость, падёж, новые поступления, перемещения между площадками (вход/выход), внешние и внутренние перемещения, пищевые отходы.","alt":"Выбор категории статистики: рождаемость, падёж, новые поступления, перемещения между площадками, внешнее перемещение"}]},"reports-web":{"title":"Отчёты (Web)","intro":"Веб-версия формирует понятные отчёты для загрузки о данных и событиях с животными — рождениях, гибели, перемещениях и оценках — на основе тех же записей, что и приложение.","summary":"Формирует понятные отчёты для загрузки о данных и событиях с животными","features":[{"title":"Фильтры и поиск","desc":"Уточняйте отчёты по дате, площадке или виду.","alt":"Общий отчёт по видам: загрузка отчёта, выбор площадки, показ/скрытие фильтров и таблица видов с количеством самцов, самок, неопределённых и неустановленных"},{"title":"Отчёты для загрузки","desc":"Формируйте, просматривайте и загружайте отчёты по видам, ежедневные, списки животных, оценки животных, по смотрителям, пользователям, наблюдениям, дневнику смотрителя, дневнику биолога и численности в вольерах — для проверок и работы офлайн.","alt":"Общий отчёт по видам: загрузка отчёта, выбор площадки, показ/скрытие фильтров и таблица видов с количеством самцов, самок, неопределённых и неустановленных"}]},"lab":{"title":"Лаборатория","intro":"Модуль «Лаборатория» централизует записи и результаты диагностических исследований, упрощает взаимодействие ветеринаров и лабораторий, помогает рано выявлять и лечить заболевания и служит защищённым цифровым хранилищем для биобезопасности, аудита и аналитики.","summary":"Централизует записи и результаты диагностических исследований, упрощает взаимодействие ветеринаров и лабораторий, помогает рано выявлять и лечить заболевания и служит защищённым хранилищем для биобезопасности, аудита и аналитики","features":[{"title":"Список заявок и фильтрация","desc":"Просматривайте и фильтруйте заявки в лабораторию по лаборатории, поиску или статусу — «Ожидает», «В работе», «Завершено» — с цветными значками.","alt":"Учёный работает с микроскопом."},{"title":"Подробный просмотр заявки","desc":"Заявитель, животное, площадка и связанная медицинская запись; обновляйте статус в реальном времени с автоматической синхронизацией между модулями.","alt":""},{"title":"Местонахождение и контроль доступа","desc":"Привязывайте лаборатории к местам; управляйте тем, кто может настраивать или просматривать данные лаборатории.","alt":""},{"title":"Привязка исследований на уровне площадки","desc":"Назначайте лаборатории для конкретных диагностических исследований прямо на вкладке настроек площадки.","alt":""},{"title":"Индивидуальное и массовое назначение","desc":"Привязывайте лаборатории к каждому исследованию или назначайте все исследования лаборатории по умолчанию одним нажатием.","alt":""},{"title":"Управление исследованиями и образцами","desc":"Создавайте и ведите лабораторные исследования, подысследования и типы образцов (сыворотка, спинномозговая жидкость и т. д.) и привязывайте их к нужным лабораториям.","alt":""},{"title":"Обновление статуса лаборатории","desc":"Отслеживайте этапы: ожидается образец → образец получен / отклонён / свернулся / гемолизирован / недостаточен → в работе → завершено (положительно / отрицательно / обнаружено / не обнаружено / неопределённо).","alt":""},{"title":"Переназначение лаборатории","desc":"При необходимости передавайте исследования в другие лаборатории без нарушения рабочего процесса.","alt":""}]},"diet":{"title":"Рацион","intro":"Модуль «Рацион» — централизованная платформа для эффективного планирования и управления рационами животных. Он позволяет командам по кормлению составлять структурированные рационы из настраиваемых компонентов, ингредиентов, типов кормов, рецептов и комбинаций и планировать кормления по времени, дню или стадии жизни.","summary":"Централизованная платформа для эффективного планирования и управления рационами животных","features":[{"title":"Настройка рациона","desc":"Составляйте рационы из типов кормов, продуктов, рецептов и смесей; планируйте кормления по времени, дню или стадии жизни; назначайте по виду или отдельному животному; активируйте, копируйте или назначайте рационы; прикрепляйте справочные материалы.","alt":"Свежие фрукты, приготовленные в качестве корма для животных."},{"title":"Способы подготовки и размер нарезки","desc":"Создавайте и ведите способы подготовки продуктов, рецептов и комбинаций для единообразия питательности и текстуры.","alt":""},{"title":"Типы кормов","desc":"Централизованный список категорий кормов с поиском для единообразного планирования рационов.","alt":""},{"title":"Продукты","desc":"Добавляйте, изменяйте и удаляйте компоненты рациона с подробными описаниями и изображениями.","alt":""},{"title":"Рецепты и смеси","desc":"Многокомпонентные рецепты и смеси: рецепты — по точным количествам, смеси — по процентному содержанию продуктов, с повторно используемыми компонентами и полным журналом действий.","alt":""},{"title":"Группы кормления","desc":"Объединяйте вольеры для согласованных графиков кормления и назначения рационов с фильтрами по площадке, секции и виду.","alt":""}]},"pharmacy-app":{"title":"Аптека (App)","intro":"Обеспечивает быструю, точную и отслеживаемую выдачу медицинских товаров непосредственно уполномоченным врачам, своевременное выполнение заявок и автоматическое обновление запасов.","summary":"Быстрая, точная и отслеживаемая выдача медицинских товаров непосредственно уполномоченным врачам","features":[{"title":"Заявки в приложении","desc":"Пользователи могут запрашивать товары в аптеке прямо через приложение.","alt":"Список выдач: 11 выдач с ID заявок, аптекой, датой, заявителем, препаратом и общим количеством, кнопка «Новая выдача»"},{"title":"Выдача в приложении","desc":"Склад может выдавать товары из аптеки прямо через приложение.","alt":"Подробности выдачи DIS279: Local Pharmacy, выдано Antz Admin, один препарат Crocin, общее количество 100"}]},"pharmacy-web":{"title":"Аптека (Web)","intro":"Обеспечивает быструю, точную и отслеживаемую выдачу медицинских товаров непосредственно уполномоченным врачам, своевременное выполнение заявок и автоматическое обновление запасов — от назначения до полки, с учётом по партиям и контролем сроков годности на всех этапах.","summary":"Быстрая, точная и отслеживаемая выдача медицинских товаров непосредственно уполномоченным врачам","features":[{"title":"Панель","desc":"Данные в реальном времени о проблемах с запасами, поставках, закупках, заявках, расходе, истекающих сроках и ходовых товарах, с наглядными тенденциями для быстрых действий.","alt":"Фармацевт раскладывает препараты по полкам."},{"title":"Умный поиск и фильтры","desc":"Быстро находите записи по ID заявки, имени врача или аптеке.","alt":""},{"title":"Справочники (стеллажи и полки)","desc":"Организуйте хранение по количеству стеллажей и полок для быстрого доступа и обновления, с настраиваемыми данными (упаковка, единицы измерения, действующие вещества, водители, производители).","alt":""},{"title":"Управление отчётами о запасах","desc":"Запасы по партиям со стоимостью и сроком годности; отметка заканчивающихся и просроченных позиций; контроль приближающихся сроков; управление депонированием с разрешением споров.","alt":""},{"title":"Управление товарами и запасами","desc":"Создавайте товары, отслеживайте запасы и сроки годности, записывайте закупки и отгрузки, ведите единую книгу учёта, работайте с заменителями и вариантами.","alt":""},{"title":"Управление выдачей","desc":"Врачи могут назначать и выдавать препараты или получать их прямо в аптеке — всё записывается.","alt":""},{"title":"Управление поставками","desc":"Отслеживайте входящие и исходящие поставки препаратов и выполняйте их в приложении.","alt":""},{"title":"Корректировка запасов и отчёты","desc":"Записывайте изменения запасов (недостача, бой, истёкший срок); храните историю аудита; оформляйте возвраты поставщикам; загружайте отчёты о расходе, возвратах, закупках и выдаче для финансов и планирования спроса.","alt":""}]},"compliance":{"title":"Соответствие требованиям","intro":"Модуль «Соответствие требованиям» даёт в приложении обзор управления животными на уровне организаций — нескольких приютов, трастов и фондов — и открывает доступ к записям об экспорте, импорте, поставках и видах, храня все нормативные документы в одном надёжном месте с возможностью загрузки.","summary":"Обзор управления животными на уровне организаций — приютов, трастов и фондов — в приложении и доступ к записям об экспорте, импорте, поставках и видах","features":[{"title":"Обзор организаций","desc":"Все зарегистрированные в системе организации в одном представлении.","alt":"Природоохранная площадка с несколькими объектами."},{"title":"Количество видов и животных","desc":"Число видов и общее количество животных каждой организации.","alt":""},{"title":"Охват площадок","desc":"Число площадок, на которых содержатся животные каждой организации.","alt":""},{"title":"Прозрачность и подотчётность","desc":"Точная отчётность и наглядные данные о популяциях животных во всех организациях.","alt":""},{"title":"Фильтры и загрузка","desc":"Фильтруйте и загружайте документы за выбранный период.","alt":""},{"title":"Экспорт и импорт","desc":"Оформляйте и изменяйте разрешительные документы на животных, вывозимых в другую страну или учреждение или ввозимых оттуда.","alt":""},{"title":"Поставка","desc":"Отслеживайте сведения о поставке: способ транспортировки, дата отправки, контейнеры, логистика.","alt":""},{"title":"Виды","desc":"Просматривайте и загружайте сведения о видах, участвующих в сделке (птицы, млекопитающие, рептилии).","alt":""},{"title":"Основные настройки","desc":"Настраивайте типы документов и ведите списки импортёров и экспортёров для записей об экспорте и импорте.","alt":""}]}}};
